<include file="Public:header"/><style type="text/css">    .table-list th{        width: 8%;    }</style><script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js"></script>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="javascript:void(0);" class="on">待提现记录</a>|					<a href="{pigcms{:U('Qiye/cashout_list')}" >已提现记录</a>				</ul>			</div>										<div class="table-list">					<table width="100%" cellspacing="0">						<thead>							<tr>                                <th>商户名称</th>								<th>提现金额</th>                                <th>姓名</th>                                <th>提现备注</th>                                <th>申请时间</th>                                <th>提现方式</th>                                <th>提现账号</th>                                <th>状态</th> 								<th>操作</th>														</thead>						<tbody>                        <notempty name="list">                            <volist name="list" id="q">                                <tr>                                    <td>{pigcms{$q.mer_name}</td>                                    <td>{pigcms{$q.money}</td>                                    <td>{pigcms{$q.name}</td>                                    <td>{pigcms{$q.remark}</td>                                    <td>{pigcms{$q.add_time|date="Y-m-d H:i:s",###}</td>                                    <td><if condition="$q['account_type'] eq 1"><font color="green">银行卡</font><else/><font color="green">支付宝</font></if></td>                                    <td>{pigcms{$q.account}</td>                                    <td>									<if condition="$q['status'] eq 0"><font color="blue">待审核</font></if>									<if condition="$q['status'] eq 1"><font color="green">通过</font></if>									<if condition="$q['status'] eq 2"><font color="red">驳回</font></if>									</td> 									<td>										<a href="javascript:void(0);" onclick="window.top.artiframe('/admin.php?g=System&c=Qiye&a=edit_reason&id={pigcms{$q.id}&type=1','编辑',500,300,true,false,false,false,'add',true);"><button>设为已兑现</button></a>										<a href="javascript:void(0);" onclick="window.top.artiframe('/admin.php?g=System&c=Qiye&a=edit_reason&id={pigcms{$q.id}&type=2','编辑',400,200,true,false,false,false,'add',true);"><button>驳回</button></a>									</td>                                </tr>                            </volist>                            <tr><td class="textcenter pagebar" colspan="13">{pigcms{$pagebar}</td></tr>                        <else/>                            <tr><td class="textcenter red" colspan="13">列表为空！</td></tr>                        </notempty>						</tbody>					</table>				</div>				</div><script type="text/javascript" src="{pigcms{$static_public}js/export.js"> </script><include file="Public:footer"/>